PRAGMA application_id=1163021388;
PRAGMA user_version=1;
CREATE TABLE catalog_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE titles(row_id INTEGER PRIMARY KEY,id TEXT UNIQUE NOT NULL,title TEXT NOT NULL,sort_title TEXT NOT NULL,year INTEGER,duration_ms INTEGER,description TEXT,poster_url TEXT,backdrop_url TEXT,created_at_ms INTEGER,updated_at_ms INTEGER,license TEXT,provenance TEXT,external_id TEXT,original_json TEXT NOT NULL);
CREATE TABLE providers(key TEXT PRIMARY KEY,label TEXT NOT NULL);
CREATE TABLE title_providers(title_row INTEGER REFERENCES titles(row_id),key TEXT REFERENCES providers(key),PRIMARY KEY(title_row,key));
CREATE TABLE sources(id TEXT PRIMARY KEY,title_row INTEGER NOT NULL REFERENCES titles(row_id),provider TEXT NOT NULL,external_id TEXT,original_url TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('FILE','HLS','EMBED')),label TEXT,quality TEXT,adapter_key TEXT,header_policy_key TEXT,provenance TEXT,original_json TEXT NOT NULL);
CREATE TABLE countries(key TEXT PRIMARY KEY,label TEXT NOT NULL);
CREATE TABLE title_countries(title_row INTEGER REFERENCES titles(row_id),key TEXT REFERENCES countries(key),PRIMARY KEY(title_row,key));
CREATE TABLE performers(key TEXT PRIMARY KEY,label TEXT NOT NULL,image_url TEXT,provenance TEXT);
CREATE TABLE title_performers(title_row INTEGER REFERENCES titles(row_id),key TEXT REFERENCES performers(key),PRIMARY KEY(title_row,key));
CREATE TABLE studios(key TEXT PRIMARY KEY,label TEXT NOT NULL);
CREATE TABLE studio_aliases(alias TEXT PRIMARY KEY,key TEXT NOT NULL REFERENCES studios(key));
CREATE TABLE title_studios(title_row INTEGER REFERENCES titles(row_id),key TEXT REFERENCES studios(key),PRIMARY KEY(title_row,key));
CREATE TABLE series(key TEXT PRIMARY KEY,label TEXT NOT NULL);
CREATE TABLE title_series(title_row INTEGER REFERENCES titles(row_id),key TEXT REFERENCES series(key),sequence INTEGER,PRIMARY KEY(title_row,key));
CREATE TABLE tags(key TEXT PRIMARY KEY,label TEXT NOT NULL,origin TEXT NOT NULL);
CREATE TABLE title_tags(title_row INTEGER REFERENCES titles(row_id),key TEXT REFERENCES tags(key),PRIMARY KEY(title_row,key));
CREATE TABLE search_documents(row_id INTEGER PRIMARY KEY REFERENCES titles(row_id),title TEXT NOT NULL,entity_text TEXT NOT NULL,description TEXT NOT NULL);
CREATE VIRTUAL TABLE titles_fts USING fts5(title,entity_text,description,content='search_documents',content_rowid='row_id',tokenize='unicode61 remove_diacritics 2');
CREATE TABLE cjk_grams(gram TEXT NOT NULL,title_row INTEGER NOT NULL REFERENCES titles(row_id),PRIMARY KEY(gram,title_row)) WITHOUT ROWID;
CREATE TABLE facet_counts(facet TEXT NOT NULL,key TEXT NOT NULL,label TEXT NOT NULL,title_count INTEGER NOT NULL,PRIMARY KEY(facet,key));
CREATE TABLE facet_cross_counts(scope_facet TEXT NOT NULL,scope_key TEXT NOT NULL,facet TEXT NOT NULL,key TEXT NOT NULL,label TEXT NOT NULL,title_count INTEGER NOT NULL,PRIMARY KEY(scope_facet,scope_key,facet,key));
CREATE TABLE facet_options(id INTEGER PRIMARY KEY,facet TEXT NOT NULL,key TEXT NOT NULL,label TEXT NOT NULL,UNIQUE(facet,key));
CREATE TABLE facet_members(title_row INTEGER NOT NULL REFERENCES titles(row_id),option_id INTEGER NOT NULL REFERENCES facet_options(id),PRIMARY KEY(title_row,option_id)) WITHOUT ROWID;
CREATE TABLE facet_bitmaps(option_id INTEGER PRIMARY KEY REFERENCES facet_options(id),bits BLOB NOT NULL);
